Files: - Create: Source/WPF/MyMoney.Data/ISaCredentialPrompt.cs - Create: Source/WPF/MyMoney.Data/SqlServerBootstrapper.cs - Test: Source/WPF/UnitTests/SqlServerBootstrapperTests.cs Interfaces: - Consumes: DatabaseRegistry / DatabaseServerEntry / DatabaseCredential (Task 1); Walkabout.Data.DataEnginePasswordGenerator.Generate(int length = 24) (existing, DataEnginePasswordGenerator.cs ); Walkabout.Data.SqlServerStoredProcDatabase.LazyCreateTables() / .Disconnect() (existing, used identically by today's BootstrapRunner.cs:99-104 ). - Produces: interface ISaCredentialPrompt { bool TryGetSaPassword(string server, out string password); } (implemented by Task 5's SaCredentialDialog , kept WPF-agnostic so this class has no WPF dependency); class SqlServerBootstrapper { SqlServerBootstrapper(string sqlScriptsRoot); bool BootstrapServerIfNeeded(DatabaseRegistry registry, string server, ISaCredentialPrompt saPrompt, out string error); bool CreateCatalog(DatabaseRegistry registry, string server, string catalogName, bool testDatabase, out string error); } . Task 6/10 call both methods; Task 12 ( DataEngineStartup ) does not call this class at all (auto-load never bootstraps — see Task 12). - Safety decision (not resolved by the spec text, made explicit here): CreateCatalog deploys all 16 Access/*.sql files to every catalog it creates (test or production), but deploys Test/*.sql files only when testDatabase == true . Deploying _Test_Reset procs into a production catalog would hand the MyMoneyTest login the ability to destructively wipe real data — the three logins get a CREATE USER in every catalog either way (needed for basic connectivity, ported unchanged from today's script), but the destructive procs themselves stay confined to catalogs the caller explicitly flagged as test databases. [ ] Step 1: Write the failing tests for the testable (non-DB) parts ExecuteBatchScript 's GO-splitting and ^USE  -skipping logic is pure string processing — factor it into an internal static method so it's unit-testable without a live SQL Server, matching the spec's explicit claim that the USE line becomes dead weight to skip. // Source/WPF/UnitTests/SqlServerBootstrapperTests.cs using NUnit.Framework; using Walkabout.Data; namespace Walkabout.UnitTests { public class SqlServerBootstrapperTests { [Test] public void SplitBatches_SplitsOnGoAndTrims() { string script = "SELECT 1;
GO
 SELECT 2; 
GO
"; var batches = SqlServerBootstrapper.SplitBatches(script); Assert.That(batches, Is.EqualTo(new[] { "SELECT 1;", "SELECT 2;" })); } [Test] public void SplitBatches_SkipsUseStatements() { string script = "USE MyMoney;
GO
SELECT 1;
GO
"; var batches = SqlServerBootstrapper.SplitBatches(script); Assert.That(batches, Is.EqualTo(new[] { "SELECT 1;" })); } [Test] public void SplitBatches_IgnoresEmptyBatches() { string script = "GO
SELECT 1;
GO

GO
"; var batches = SqlServerBootstrapper.SplitBatches(script); Assert.That(batches, Is.EqualTo(new[] { "SELECT 1;" })); } } } [ ] Step 2: Run to verify failure Run: dotnet test Source/WPF/UnitTests/UnitTests.csproj --filter "FullyQualifiedName~SqlServerBootstrapperTests" Expected: FAIL — SqlServerBootstrapper doesn't exist. [ ] Step 3: Implement ISaCredentialPrompt and SqlServerBootstrapper // Source/WPF/MyMoney.Data/ISaCredentialPrompt.cs namespace Walkabout.Data { /// <summary> /// Kept WPF-agnostic so SqlServerBootstrapper (MyMoney.Data, no WPF /// reference) can prompt for 'sa' without depending on the UI layer. /// Implemented by MyMoney's SaCredentialDialog. /// </summary> public interface ISaCredentialPrompt { /// <returns>false if the user cancelled.</returns> bool TryGetSaPassword(string server, out string password); } } // Source/WPF/MyMoney.Data/SqlServerBootstrapper.cs using System; using System.IO; using System.Text.RegularExpressions; using Microsoft.Data.SqlClient; namespace Walkabout.Data { public class SqlServerBootstrapper { private readonly string sqlScriptsRoot; private static readonly string[] AccessProcFiles = { "Payees_AccessProcs.sql", "Accounts_AccessProcs.sql", "Categories_AccessProcs.sql", "Currencies_AccessProcs.sql", "Securities_AccessProcs.sql", "StockSplits_AccessProcs.sql", "Aliases_AccessProcs.sql", "Transactions_AccessProcs.sql", "Splits_AccessProcs.sql", "Investments_AccessProcs.sql", "OnlineAccounts_AccessProcs.sql", "AccountAliases_AccessProcs.sql", "TransactionExtras_AccessProcs.sql", "LoanPayments_AccessProcs.sql", "RentUnits_AccessProcs.sql", "RentBuildings_AccessProcs.sql" }; public SqlServerBootstrapper(string sqlScriptsRoot) { this.sqlScriptsRoot = sqlScriptsRoot; } public bool BootstrapServerIfNeeded(DatabaseRegistry registry, string server, ISaCredentialPrompt saPrompt, out string error) { error = null; if (registry.Servers.ContainsKey(server)) { return true; } if (!saPrompt.TryGetSaPassword(server, out string saPassword)) { error = "Bootstrap cancelled."; return false; } string adminPassword = DataEnginePasswordGenerator.Generate(); string userPassword = DataEnginePasswordGenerator.Generate(); string testPassword = DataEnginePasswordGenerator.Generate(); var saBuilder = new SqlConnectionStringBuilder { DataSource = server, UserID = "sa", Password = saPassword, InitialCatalog = "master", TrustServerCertificate = true, ConnectTimeout = 10 }; try { DeployScript(saBuilder.ConnectionString, Path.Combine(this.sqlScriptsRoot, "Bootstrap", "MyMoney_BootstrapServer.sql")); using (var connection = new SqlConnection(saBuilder.ConnectionString)) { connection.Open(); using (var command = new SqlCommand("master.dbo.MyMoney_BootstrapServer", connection) { CommandType = System.Data.CommandType.StoredProcedure }) { command.Parameters.AddWithValue("@AdminPassword", adminPassword); command.Parameters.AddWithValue("@UserPassword", userPassword); command.Parameters.AddWithValue("@TestPassword", testPassword); command.ExecuteNonQuery(); } } } catch (Exception ex) { error = $"Could not bootstrap server '{server}' as 'sa': {ex.Message}"; return false; } // sa's password is never persisted (Global Constraints) -- only // the three generated role passwords go into the registry. registry.Servers[server] = new DatabaseServerEntry { MyMoneyAdmin = new DatabaseCredential { UserId = "MyMoneyAdmin", Password = adminPassword }, MyMoneyUser = new DatabaseCredential { UserId = "MyMoneyUser", Password = userPassword }, MyMoneyTest = new DatabaseCredential { UserId = "MyMoneyTest", Password = testPassword } }; registry.Save(); return true; } public bool CreateCatalog(DatabaseRegistry registry, string server, string catalogName, bool testDatabase, out string error) { error = null; if (!registry.Servers.TryGetValue(server, out DatabaseServerEntry serverEntry)) { error = $"Server '{server}' has not been bootstrapped yet."; return false; } var adminBuilder = new SqlConnectionStringBuilder { DataSource = server, UserID = serverEntry.MyMoneyAdmin.UserId, Password = serverEntry.MyMoneyAdmin.Password, InitialCatalog = "master", TrustServerCertificate = true, ConnectTimeout = 10 }; try { DeployScript(adminBuilder.ConnectionString, Path.Combine(this.sqlScriptsRoot, "Bootstrap", "MyMoney_CreateCatalog.sql")); using (var connection = new SqlConnection(adminBuilder.ConnectionString)) { connection.Open(); using (var command = new SqlCommand("master.dbo.MyMoney_CreateCatalog", connection) { CommandType = System.Data.CommandType.StoredProcedure }) { command.Parameters.AddWithValue("@CatalogName", catalogName); command.ExecuteNonQuery(); } } var catalogBuilder = new SqlConnectionStringBuilder(adminBuilder.ConnectionString) { InitialCatalog = catalogName }; var adminDatabase = new SqlServerStoredProcDatabase { ConnectionStringOverride = catalogBuilder.ConnectionString }; adminDatabase.LazyCreateTables(); adminDatabase.Disconnect(); foreach (string procFile in AccessProcFiles) { string script = File.ReadAllText(Path.Combine(this.sqlScriptsRoot, "Access", procFile)); ExecuteBatchScript(catalogBuilder.ConnectionString, script); } if (testDatabase) { // Test/_Test_Reset procs are destructive-wipe capable -- // only ever deployed into a catalog the caller flagged // as a test database (see this task's Safety decision). foreach (string testFile in Directory.GetFiles(Path.Combine(this.sqlScriptsRoot, "Test"), "*.sql")) { ExecuteBatchScript(catalogBuilder.ConnectionString, File.ReadAllText(testFile)); } } } catch (Exception ex) { error = $"Could not create catalog '{catalogName}' on '{server}': {ex.Message}"; return false; } return true; } private static void DeployScript(string connectionString, string scriptPath) { ExecuteBatchScript(connectionString, File.ReadAllText(scriptPath)); } /// <summary> /// Ported from MyMoneyAdmin's BootstrapRunner.ExecuteBatchScript, /// plus skipping any batch matching ^USE  -- the connection is /// already scoped to the right catalog via InitialCatalog, so the /// checked-in scripts' leading "USE &lt;db&gt;;" line (kept for a human /// running them by hand in SSMS) is dead weight for us. /// </summary> private static void ExecuteBatchScript(string connectionString, string script) { using (var connection = new SqlConnection(connectionString)) { connection.Open(); foreach (string batch in SplitBatches(script)) { using (var command = new SqlCommand(batch, connection) { CommandTimeout = 60 }) { command.ExecuteNonQuery(); } } } } internal static string[] SplitBatches(string script) { string[] rawBatches = script.Split(new[] { "
GO", "
GO" }, StringSplitOptions.RemoveEmptyEntries); var batches = new System.Collections.Generic.List<string>(); foreach (string raw in rawBatches) { string trimmed = raw.Trim(); if (trimmed.Length == 0 || Regex.IsMatch(trimmed, @"^USE ", RegexOptions.IgnoreCase)) { continue; } batches.Add(trimmed); } return batches.ToArray(); } } } [ ] Step 4: Run to verify pass Run: dotnet test Source/WPF/UnitTests/UnitTests.csproj --filter "FullyQualifiedName~SqlServerBootstrapperTests" Expected: PASS (3 tests). [ ] Step 5: Commit git add Source/WPF/MyMoney.Data/ISaCredentialPrompt.cs Source/WPF/MyMoney.Data/SqlServerBootstrapper.cs Source/WPF/UnitTests/SqlServerBootstrapperTests.cs git commit -m "feat: add in-process SqlServerBootstrapper, replacing MyMoneyAdmin's BootstrapRunner (#32)" (Live-server behavior — actually calling MyMoney_BootstrapServer / MyMoney_CreateCatalog against Redmond, idempotency on a second run, a genuinely new second catalog — is verified in Task 13, not here; this task's tests cover only the DB-free string logic.)
